int main() {
    int T, n;
    cin>>T>>n;
    vector<int> times(n);
    vector<int> reward(n);
    // 滚动数组
    vector<int> ans(T+1, 0);
    for (int i = 0; i < n; i++) {
        int t, w;
        cin >> t >> w;
        // 从后往前防止被覆盖
        for (int j = T; j >=0; j--) {
            if (j < t) {
                break;
            }
            ans[j] = max(ans[j], w + ans[j-t]);
        }
    }
​
    cout << ans[T];
    return 0;
}

JAVA:
import java.util.Scanner;
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        int n = scanner.nextInt();
        int[] dp = new int[T + 1];
​
        for (int i = 0; i < n; i++) {
            int t = scanner.nextInt();
            int w = scanner.nextInt();
            // 逆序遍历，防止覆盖
            for (int j = T; j >= t; j--) {
                dp[j] = Math.max(dp[j], dp[j - t] + w);
            }
        }
​
        System.out.println(dp[T]);
        scanner.close();
    }
}
