    input: process.stdin,
    output: process.stdout
});
​
let input = [];
rl.on("line", (line) => {
    input.push(line);
}).on("close", () => {
    const [T, n] = input[0].split(" ").map(Number);
    let dp = new Array(T + 1).fill(0);
​
    for (let i = 1; i <= n; i++) {
        let [t, w] = input[i].split(" ").map(Number);
        // 逆序遍历，防止覆盖
        for (let j = T; j >= t; j--) {
            dp[j] = Math.max(dp[j], dp[j - t] + w);
        }
    }
​
    console.log(dp[T]);
});
