package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    parts := strings.Fields(line)
    T, _ := strconv.Atoi(parts[0])
    n, _ := strconv.Atoi(parts[1])
​
    dp := make([]int, T+1)
​
    for i := 0; i < n; i++ {
        line, _ := reader.ReadString('\n')
        parts := strings.Fields(line)
        t, _ := strconv.Atoi(parts[0])
        w, _ := strconv.Atoi(parts[1])
​
        // 逆序遍历，防止覆盖
        for j := T; j >= t; j-- {
            if dp[j-t]+w > dp[j] {
                dp[j] = dp[j-t] + w
            }
        }
    }
​
    fmt.Println(dp[T])
}
